 }
 void ValidateTimeCell(object sender,DataGridCellEditEndingEventArgs e){if(e.EditAction!=DataGridEditAction.Commit||(e.Column!=table.Columns[2]&&e.Column!=table.Columns[3]))return;var editor=e.EditingElement as TextBox;if(editor==null)return;try{editor.Text=Schedule.NormalizeTime(editor.Text,false);}catch(Exception ex){e.Cancel=true;feedback.Text=((Lesson)e.Row.Item).Name+" · "+e.Column.Header+": "+ex.Message;}}
 void CheckTimetable(){try{foreach(var lesson in rows)Schedule.ValidateName(lesson.Name);Schedule.Validate(rows.ToList());feedback.Text="Timetable checked: no time conflicts.";}catch(Exception ex){feedback.Text=ex.Message;}}
 internal void SortByDay(bool descending){var list=(ListCollectionView)CollectionViewSource.GetDefaultView(rows);list.CustomSort=new DayLessonComparer(descending);foreach(var column in table.Columns)column.SortDirection=null;table.Columns[0].SortDirection=descending?ListSortDirection.Descending:ListSortDirection.Ascending;table.Columns[2].SortDirection=ListSortDirection.Ascending;}
 internal void HandleSorting(object sender,DataGridSortingEventArgs e){if(!Commit()){e.Handled=true;return;}if(e.Column==table.Columns[0]){e.Handled=true;SortByDay(e.Column.SortDirection==ListSortDirection.Ascending);}else{((ListCollectionView)CollectionViewSource.GetDefaultView(rows)).CustomSort=null;}}
 bool Commit(){if(table==null)return true;if(!table.CommitEdit(DataGridEditingUnit.Cell,true)||!table.CommitEdit(DataGridEditingUnit.Row,true)){feedback.Text="Please finish editing the highlighted cell. Warning minutes must be a whole number.";return false;}return true;}
 void ImportCsv(){if(!Commit())return;var dialog=new OpenFileDialog{Title="Import timetable CSV",Filter="CSV UTF-8 (*.csv)|*.csv",CheckFileExists=true};if(dialog.ShowDialog(this)!=true)return;Try(delegate{var imported=ScheduleCsv.Read(dialog.FileName);var candidate=importMode.SelectedIndex==1?rows.Concat(imported).ToList():imported;Schedule.Validate(candidate);rows.Clear();foreach(var lesson in candidate)rows.Add(lesson);feedback.Text=imported.Count+" lessons imported into the draft. Review and Save to apply.";});}
 static Brush Contrast(string value){var c=(Color)ColorConverter.ConvertFromString(value);return c.R*0.299+c.G*0.587+c.B*0.114<140?Brushes.White:Dial.Brush("#193B50");}
 static bool ValidColour(string value){return System.Text.RegularExpressions.Regex.IsMatch(value??"",@"^#[0-9a-fA-F]{6}$");}
 TextBox ColourRow(Panel panel,string label,string initial,Action changed){Label(panel,label);var row=new DockPanel();var value=new TextBox{Text=initial,MaxLength=7,Width=110,HorizontalAlignment=HorizontalAlignment.Left};var picker=Button("Choose…",delegate{using(var dialog=new Forms.ColorDialog{FullOpen=true}){if(ValidColour(value.Text))dialog.Color=System.Drawing.ColorTranslator.FromHtml(value.Text);if(dialog.ShowDialog()==Forms.DialogResult.OK)value.Text=String.Format("#{0:X2}{1:X2}{2:X2}",dialog.Color.R,dialog.Color.G,dialog.Color.B);}});picker.Background=Dial.Brush(initial);picker.Foreground=Contrast(initial);DockPanel.SetDock(picker,Dock.Right);row.Children.Add(picker);row.Children.Add(value);panel.Children.Add(row);value.TextChanged+=delegate{if(ValidColour(value.Text)){picker.Background=Dial.Brush(value.Text);picker.Foreground=Contrast(value.Text);}changed();};return value;}
