 static Grid SoundGrid(){var g=new Grid();g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});for(int i=0;i<3;i++)g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(78)});g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(90)});return g;}
 static void AddSoundCell(Grid grid,UIElement element,int column){Grid.SetColumn(element,column);grid.Children.Add(element);}
 internal void RefreshSounds(string selected){soundList.Items.Clear();foreach(var original in controller.Sounds.Choices().Where(c=>!removedSounds.Contains(c.Id))){var choice=new SoundChoice{Id=original.Id,Label=soundNames.ContainsKey(original.Id)?soundNames[original.Id]:original.Label};var item=new ListBoxItem{Tag=choice,HorizontalContentAlignment=HorizontalAlignment.Stretch,Padding=new Thickness(6,2,6,2)};var grid=SoundGrid();item.Content=grid;AddSoundCell(grid,new TextBlock{Text=choice.Label,TextTrimming=TextTrimming.CharacterEllipsis,ToolTip=choice.Label,VerticalAlignment=VerticalAlignment.Center},0);
   string[] selections={draft.StartSound,draft.WarningSound,draft.EndSound};for(int i=0;i<3;i++){int column=i;var radio=new RadioButton{GroupName=Guid.NewGuid().ToString("N"),IsChecked=selections[i]==choice.Id,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,ToolTip=new[]{"Start","Warning","End"}[i]+": "+choice.Label};radio.Checked+=delegate{if(syncingSounds)return;if(column==0)draft.StartSound=choice.Id;else if(column==1)draft.WarningSound=choice.Id;else draft.EndSound=choice.Id;soundList.SelectedItem=item;SyncSoundRadios();};AddSoundCell(grid,radio,i+1);}
   var preview=Button("Preview",delegate{soundList.SelectedItem=item;Try(delegate{controller.Sounds.Play(choice.Id);});});preview.Padding=new Thickness(8,4,8,4);AddSoundCell(grid,preview,4);soundList.Items.Add(item);if(choice.Id==selected)soundList.SelectedItem=item;
  }if(soundList.SelectedItem==null&&soundList.Items.Count>0)soundList.SelectedIndex=0;SyncSoundRadios();
 }
 bool syncingSounds;
 void SyncSoundRadios(){if(syncingSounds)return;syncingSounds=true;try{string[] selected={draft.StartSound,draft.WarningSound,draft.EndSound};foreach(ListBoxItem item in soundList.Items){string id=((SoundChoice)item.Tag).Id;var radios=((Grid)item.Content).Children.OfType<RadioButton>().ToArray();for(int i=0;i<radios.Length;i++)radios[i].IsChecked=selected[i]==id;}}finally{syncingSounds=false;}}
 string SelectedSound(){var item=soundList.SelectedItem as ListBoxItem;if(item==null)throw new InvalidDataException("Select an imported sound first.");string id=((SoundChoice)item.Tag).Id;if(!controller.Sounds.IsCustom(id))throw new InvalidDataException("Built-in sounds cannot be renamed or deleted.");return id;}
 void RenameSound(){Try(delegate{string id=SelectedSound();string name=soundName.Text.Trim();if(name.Length==0||name.Length>80)throw new InvalidDataException("Enter a sound name of 1–80 characters.");soundNames[id]=name;RefreshSounds(id);feedback.Text="Sound renamed in this draft. Save to apply.";});}
 void DeleteSound(){Try(delegate{string id=SelectedSound();controller.Sounds.Stop();removedSounds.Add(id);soundNames.Remove(id);if(draft.StartSound==id)draft.StartSound="Chime";if(draft.WarningSound==id)draft.WarningSound="Soft bell";if(draft.EndSound==id)draft.EndSound="Double bell";RefreshSounds(null);feedback.Text="Sound marked for deletion. Its assigned alerts now use built-in defaults. Save to apply, or Close without saving to keep it.";});}
 async void ImportAudio(){if(importing)return;var pick=new OpenFileDialog{Title="Choose a custom alert sound",Filter="Audio (*.wav;*.mp3;*.wma;*.m4a;*.aac)|*.wav;*.mp3;*.wma;*.m4a;*.aac",CheckFileExists=true};if(pick.ShowDialog(this)!=true)return;importing=true;importSound.IsEnabled=false;feedback.Text="Copying and checking audio…";try{string id=await controller.Sounds.ImportAsync(pick.FileName);if(!closed){RefreshSounds(id);feedback.Text="Sound copied and checked. Choose its Start, Warning or End buttons, then save.";}}catch(Exception ex){if(!closed)feedback.Text=ex.Message;}finally{importing=false;if(!closed)importSound.IsEnabled=true;}}
