 void Try(Action a){try{a();}catch(Exception ex){feedback.Text=ex.Message;}}
 internal void Save(){if(importing){feedback.Text="Please wait for the audio import to finish.";return;}if(!Commit())return;Try(delegate{draft.WarningColour=warningColour.Text;draft.TextColour=textColour.Text;draft.FillColour=fillColour.Text;draft.BorderColour=borderColour.Text;draft.View=(string)view.SelectedItem;draft.Scale=scale.Value;draft.Lessons=rows.ToList();foreach(var lesson in draft.Lessons)Schedule.ValidateName(lesson.Name);controller.Apply(draft);foreach(var entry in soundNames)controller.Sounds.Rename(entry.Key,entry.Value);foreach(var id in removedSounds)controller.Sounds.Delete(id);if(Startup.Enabled!=(startWithWindows.IsChecked==true))Startup.SetEnabled(startWithWindows.IsChecked==true);soundNames.Clear();removedSounds.Clear();RefreshSounds(null);feedback.Text="Settings saved and applied.";});}
}
